import('./server.mjs').then(async ({callTool}) => {
  // invalid steps (zero)
  try { await callTool('run_with_progress',{steps:0}); console.log('ERROR: should have thrown for steps=0'); }
  catch(e){ console.log('OK rejected steps=0:', e.message); }
  // invalid steps (non-integer)
  try { await callTool('run_with_progress',{steps:2.5}); console.log('ERROR: should have thrown for steps=2.5'); }
  catch(e){ console.log('OK rejected steps=2.5:', e.message); }
  // negative
  try { await callTool('run_with_progress',{steps:-3}); console.log('ERROR: should have thrown for steps=-3'); }
  catch(e){ console.log('OK rejected steps=-3:', e.message); }
  // unknown tool
  try { await callTool('nope',{steps:1}); console.log('ERROR: should have thrown for unknown tool'); }
  catch(e){ console.log('OK rejected unknown tool:', e.message, 'code', e.code); }
  // no callback - just completes
  const r = await callTool('run_with_progress',{steps:3});
  console.log('OK no-callback result:', JSON.stringify(r));
  // 4 steps -> [0, 0.25, 0.5, 0.75, 1]
  const v=[]; await callTool('run_with_progress',{steps:4},{onProgress:x=>v.push(x)});
  console.log('OK 4-step progress:', JSON.stringify(v));
});
""}

